example:
class Lamp
{
    public virtual string Glow()
    {
        return "dim";
    }
}

class Torch : Lamp
{
    public override string Glow()
    {
        return "flame";
    }
}

class Crystal : Lamp
{
    public override string Glow()
    {
        return "blue";
    }
}

class Hall
{
    public string Light()
    {
        Lamp[] lamps = { new Lamp(), new Torch(), new Crystal() };
        string text = "";
        foreach (Lamp lamp in lamps)
        {
            text += lamp.Glow() + " ";
        }

        return text;
    }
}
